module top_module (
    input [5:0] y,
    input w,
    output Y1,
    output Y3
);

    // State Encoding (One-Hot):
    // y[0] = A, y[1] = B, y[2] = C, y[3] = D, y[4] = E, y[5] = F

    // Y1 drives the flip-flop for state B (y[1]).
    // Next state is B only if current state is A (y[0]) and input w is 1.
    // Transition: A --1--> B
    assign Y1 = y[0] & w;

    // Y3 drives the flip-flop for state D (y[3]).
    // Next state is D if current state is B, C, E, or F and input w is 0.
    // Transitions: B --0--> D, C --0--> D, E --0--> D, F --0--> D
    assign Y3 = (~w) & (y[1] | y[2] | y[4] | y[5]);

endmodule

