module top_module (
    input clk,
    input resetn,
    input [3:1] r,
    output [3:1] g
);

    // State encoding
    parameter S_A = 2'b00;
    parameter S_B = 2'b01;
    parameter S_C = 2'b10;
    parameter S_D = 2'b11;

    // State registers
    reg [1:0] current_state;
    reg [1:0] next_state;

    // State Flip-Flops (Sequential Logic)
    // Synchronous active-low reset
    always @(posedge clk) begin
        if (!resetn) begin
            current_state <= S_A;
        end else begin
            current_state <= next_state;
        end
    end

    // State Table (Combinational Logic)
    always @(*) begin
        case (current_state)
            S_A: begin
                // Priority: Device 1 > Device 2 > Device 3
                // If r1 is high, grant device 1 (State B)
                if (r[1])
                    next_state = S_B;
                // Else if r2 is high, grant device 2 (State C)
                else if (r[2])
                    next_state = S_C;
                // Else if r3 is high, grant device 3 (State D)
                else if (r[3])
                    next_state = S_D;
                // Else no requests, stay in Idle (State A)
                else
                    next_state = S_A;
            end
            S_B: begin
                // Grant to Device 1. Stay if request persists, else return to A.
                if (r[1])
                    next_state = S_B;
                else
                    next_state = S_A;
            end
            S_C: begin
                // Grant to Device 2. Stay if request persists, else return to A.
                if (r[2])
                    next_state = S_C;
                else
                    next_state = S_A;
            end
            S_D: begin
                // Grant to Device 3. Stay if request persists, else return to A.
                if (r[3])
                    next_state = S_D;
                else
                    next_state = S_A;
            end
            default: next_state = S_A;
        endcase
    end

    // Output Logic (Combinational)
    // Moore outputs depend only on current state
    assign g[1] = (current_state == S_B);
    assign g[2] = (current_state == S_C);
    assign g[3] = (current_state == S_D);

endmodule

