module top_module (
    input clk,
    input resetn,
    input [3:1] r,
    output [3:1] g
);

    // State Encoding
    // A: Idle state (No grants)
    // B: Grant to Device 1
    // C: Grant to Device 2
    // D: Grant to Device 3
    localparam [1:0] A = 2'b00;
    localparam [1:0] B = 2'b01;
    localparam [1:0] C = 2'b10;
    localparam [1:0] D = 2'b11;

    reg [1:0] current_state;
    reg [1:0] next_state;

    // State Table (Next State Logic)
    // Combinational logic determines the next state based on current state and inputs.
    always @(*) begin
        case (current_state)
            A: begin
                // Priority Logic: Device 1 > Device 2 > Device 3
                // Transition to D occurs when r[3] is high and r[1], r[2] are low.
                // (Correcting diagram typo 'r3=0' to 'r3=1' based on functional description)
                if (r[1]) next_state = B;
                else if (r[2]) next_state = C;
                else if (r[3]) next_state = D;
                else next_state = A;
            end
            B: begin
                // Stay in B as long as Device 1 requests (r[1]=1)
                if (r[1]) next_state = B;
                else next_state = A;
            end
            C: begin
                // Stay in C as long as Device 2 requests (r[2]=1)
                if (r[2]) next_state = C;
                else next_state = A;
            end
            D: begin
                // Stay in D as long as Device 3 requests (r[3]=1)
                if (r[3]) next_state = D;
                else next_state = A;
            end
            default: next_state = A;
        endcase
    end

    // State Flip-Flops (Current State Register)
    // Sequential logic updates the current state on the rising edge of the clock.
    // resetn is an active-low synchronous reset.
    always @(posedge clk) begin
        if (!resetn) begin
            current_state <= A;
        end else begin
            current_state <= next_state;
        end
    end

    // Output Logic
    // Outputs depend on the current state (Moore Machine).
    // g[1] active in State B, g[2] active in State C, g[3] active in State D.
    assign g[1] = (current_state == B);
    assign g[2] = (current_state == C);
    assign g[3] = (current_state == D);

endmodule

