    // States: [2:0] = [cycle_count(0-2), ones_count(0-3)]
    // But we encode as: state = cycle_count * 4 + ones_count
    localparam [3:0] STATE_A = 4'd0;
    localparam [3:0] STATE_0_0 = 4'd0; // cycle 0, ones 0
    localparam [3:0] STATE_0_1 = 4'd1; // cycle 0, ones 1
    localparam [3:0] STATE_1_0 = 4'd4; // cycle 1, ones 0
    localparam [3:0] STATE_1_1 = 4'd5; // cycle 1, ones 1
    localparam [3:0] STATE_1_2 = 4'd6; // cycle 1, ones 2
