module top_module (
    input clk,
    input reset,
    input s,
    input w,
    output reg z
);

    parameter [3:0] A = 4'd0;
    parameter [3:0] C0_0 = 4'd1;
    parameter [3:0] C1_0 = 4'd2;
    parameter [3:0] C1_1 = 4'd3;
    parameter [3:0] C2_0 = 4'd4;
    parameter [3:0] C2_1 = 4'd5;
    parameter [3:0] C2_2 = 4'd6;
    parameter [3:0] OUT_0 = 4'd7;
    parameter [3:0] OUT_1 = 4'd8;

    reg [3:0] state, next_state;

    // State register
    always @(posedge clk) begin
        if (reset)
            state <= A;
        else
            state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (state)
            A: begin
                if (s)
                    next_state = C0_0;
                else
                    next_state = A;
            end
            C0_0: begin
                if (w)
                    next_state = C1_1;
                else
                    next_state = C1_0;
            end
            C1_0: begin
                if (w)
                    next_state = C2_1;
                else
                    next_state = C2_0;
            end
            C1_1: begin
                if (w)
                    next_state = C2_2;
                else
                    next_state = C2_1;
            end
            C2_0: begin
                next_state = OUT_0;
            end
            C2_1: begin
                if (w)
                    next_state = OUT_1;
                else
                    next_state = OUT_0;
            end
            C2_2: begin
                if (w)
                    next_state = OUT_0;
                else
                    next_state = OUT_1;
            end
            OUT_0: begin
                next_state = C0_0;
            end
            OUT_1: begin
                next_state = C0_0;
            end
            default: next_state = A;
        endcase
    end

    // Output logic
    always @(*) begin
