            C0_0: z = 0;
            C1_0: z = 0;
            C1_1: z = 0;
            C2_0: z = 0;
            C2_1: z = 0;
            C2_2: z = 0;
            OUT_0: z = 0;
            OUT_1: z = 1;
            default: z = 0;
        endcase
    end

