module top_module (
	input clk,
	input reset,
	input s,
	input w,
	output reg z
);

    // State Encoding
    // S_A: Reset state
    // S_B: 1st cycle of window (Output z based on prev window)
    // S_C: 2nd cycle of window
    // S_D: 3rd cycle of window
    parameter S_A = 2'b00;
    parameter S_B = 2'b01;
    parameter S_C = 2'b10;
    parameter S_D = 2'b11;

    reg [1:0] state;
    reg [1:0] cnt; // Counter to track number of 1s in the current 3-cycle window

    always @(posedge clk) begin
        if (reset) begin
            state <= S_A;
            cnt <= 0;
            z <= 0;
        end else begin
            // State Transition Logic
            case (state)
                S_A: if (s) state <= S_B; else state <= S_A;
                S_B: state <= S_C;
                S_C: state <= S_D;
                S_D: state <= S_B;
                default: state <= S_A;
            endcase

            // Counter Update Logic
            case (state)
                S_A: cnt <= 0;
                S_B: cnt <= w;      // Start of new window, reset count to current w
                S_C: cnt <= cnt + w;
                S_D: cnt <= cnt + w;
            endcase

            // Output Logic
            // z is 1 in S_B if the count from the previous window was exactly 2
            // Note: 'cnt' here holds the value from the end of the previous cycle (S_D)
            if (state == S_B && cnt == 2)
                z <= 1;
            else
                z <= 0;
