module top_module (
    input clock,
    input a,
    output reg p,
    output reg q
);

    // This circuit is a sequential state machine that tracks input 'a'
    // p follows 'a' when clock is high
    // q latches the value of 'p' when clock transitions from 1 to 0

    always @(posedge clock or negedge clock) begin
        if (clock) begin
            // When clock is high, p follows input a
            p <= a;
        end else begin
            // When clock goes low, q captures the current value of p
            q <= p;
        end
    end

