module top_module(
	input clk,
	input load,
	input [255:0] data,
	output reg [255:0] q);

    integer i, x, y, dx, dy, nx, ny, neighbor_count;
    reg [255:0] next_q;

    always @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            for (i = 0; i < 256; i = i + 1) begin
                y = i >> 4;
                x = i & 15;
                neighbor_count = 0;

                for (dy = -1; dy <= 1; dy = dy + 1) begin
                    for (dx = -1; dx <= 1; dx = dx + 1) begin
                        if (dx == 0 && dy == 0) continue;

                        // Wrap around logic for toroidal grid
                        // Adding 16 ensures the result is positive before modulo
                        nx = (x + dx + 16) % 16;
                        ny = (y + dy + 16) % 16;

                        // Calculate neighbor index: row * 16 + col
                        neighbor_count = neighbor_count + q[ny * 16 + nx];
                    end
                end

                // Apply Game of Life rules
                if (neighbor_count == 3)
                    next_q[i] = 1'b1;
                else if (neighbor_count == 2)
                    next_q[i] = q[i];
                else
                    next_q[i] = 1'b0;
            end
            q <= next_q;
        end
    end

