        for (r = 0; r < 16; r = r + 1) begin
            for (c = 0; c < 16; c = c + 1) begin
                i = r * 16 + c;
                count = 0;

                // Top-Left neighbor
                nr = (r == 0) ? 15 : r - 1;
                nc = (c == 0) ? 15 : c - 1;
                count = count + q[nr * 16 + nc];

                // Top neighbor
                nr = (r == 0) ? 15 : r - 1;
                nc = c;
                count = count + q[nr * 16 + nc];

                // Top-Right neighbor
                nr = (r == 0) ? 15 : r - 1;
                nc = (c == 15) ? 0 : c + 1;
                count = count + q[nr * 16 + nc];

                // Left neighbor
                nr = r;
                nc = (c == 0) ? 15 : c - 1;
                count = count + q[nr * 16 + nc];

