module top_module(
	input clk,
	input load,
	input [255:0] data,
	output reg [255:0] q);

    // Combinational logic to compute the next state of the grid
    wire [255:0] next_q;
    genvar i, j;

    generate
        // Iterate over each row (0-15)
        for(i=0; i<16; i=i+1) begin : row_gen
            // Iterate over each column (0-15)
            for(j=0; j<16; j=j+1) begin : col_gen
                // Calculate neighbor row indices with toroidal wrapping
                wire [3:0] r_prev = (i == 0) ? 4'd15 : i - 1;
                wire [3:0] r_curr = i;
                wire [3:0] r_next = (i == 15) ? 4'd0 : i + 1;

                // Calculate neighbor column indices with toroidal wrapping
                wire [3:0] c_prev = (j == 0) ? 4'd15 : j - 1;
                wire [3:0] c_curr = j;
                wire [3:0] c_next = (j == 15) ? 4'd0 : j + 1;

                // Sum the 8 neighbors
                // q is indexed as q[row*16 + col], which is {row, col}
                wire [3:0] neighbors;
                assign neighbors = 
                    q[{r_prev, c_prev}] + q[{r_prev, c_curr}] + q[{r_prev, c_next}] +
                    q[{r_curr, c_prev}] +                       q[{r_curr, c_next}] +
                    q[{r_next, c_prev}] + q[{r_next, c_curr}] + q[{r_next, c_next}];

                // Determine next state based on Game of Life rules
                wire next_bit;
                assign next_bit = (neighbors == 3) ? 1'b1 : 
                                  ((neighbors == 2) ? q[{r_curr, c_curr}] : 1'b0);

                // Assign the computed bit to the next state vector
                assign next_q[{i, j}] = next_bit;
            end
        end
    endgenerate

    // Sequential logic to update the state register
    always @(posedge clk) begin
        if (load)
            q <= data;
        else
            q <= next_q;
    end

