    reg [255:0] next_q;
    integer i, r, c, nr, nc, n, r_idx, c_idx, bit_idx;

    // Combinational logic to compute the next state of the grid
    always @(*) begin
        next_q = 0; // Initialize to avoid latches (though loop covers all bits)

        for (i = 0; i < 256; i = i + 1) begin
            r = i >> 4;       // Row index (0-15)
            c = i & 15;       // Col index (0-15)
            n = 0;            // Neighbor count

            // Iterate over 3x3 neighborhood
            for (nr = r - 1; nr <= r + 1; nr = nr + 1) begin
                for (nc = c - 1; nc <= c + 1; nc = nc + 1) begin
                    // Skip the cell itself
                    if (nr == r && nc == c) continue;

                    // Handle toroidal wrapping (modulo 16)
                    // Using bitwise AND for efficiency since 16 is power of 2
                    // nr & 15 handles wrapping for range -1 to 16 correctly in 2's complement
                    r_idx = nr & 15;
                    c_idx = nc & 15;

                    bit_idx = (r_idx << 4) | c_idx;

                    // Count alive neighbors
                    n = n + q[bit_idx];
                end
            end

            // Apply Game of Life rules
            if (n == 3)
                next_q[i] = 1;
            else if (n == 2)
                next_q[i] = q[i];
            else
                next_q[i] = 0;
        end
    end

    // Sequential logic to update the grid state on clock edge
    always @(posedge clk) begin
        if (load)
            q <= data;
        else
            q <= next_q;
    end

