module top_module (
	input a,
	input b,
	input c,
	input d,
	output out_sop,
	output out_pos
);

// SOP: a'b'c + cd
// Covers minterms 2, 3, 7, 11, 15 (3 and 11 are don't cares)
assign out_sop = (~a & ~b & c) | (c & d);

// POS: (a+c) * (b'+c'+d) * (a'+c+d') * (a'+c'+d)
// Covers maxterms for 0s at 0,1,4,5,6,9,10,13,14
assign out_pos = (a | c) & (~b | ~c | d) & (~a | c | ~d) & (~a | ~c | d);

endmodule

